class FenwickTree(private val n: Int) {
    private val tree = LongArray(n + 1)                  // 1-indexed internally

    constructor(values: IntArray) : this(values.size) {  // O(n) build
        for (i in values.indices) tree[i + 1] += values[i].toLong()
        for (i in 1..n) {
            val parent = i + (i and -i)
            if (parent <= n) tree[parent] += tree[i]     // push each cell's total into its parent
        }
    }

    // add delta to position index (0-based)
    fun update(index: Int, delta: Long) {
        var i = index + 1
        while (i <= n) {
            tree[i] += delta
            i += i and -i                                // jump to the next cell that covers this index
        }
    }

    // sum of positions 0..index
    fun prefixSum(index: Int): Long {
        var i = index + 1
        var sum = 0L
        while (i > 0) {
            sum += tree[i]
            i -= i and -i                                // drop the lowest set bit
        }
        return sum
    }

    // sum of positions l..r (inclusive)
    fun rangeSum(l: Int, r: Int): Long = prefixSum(r) - (if (l > 0) prefixSum(l - 1) else 0L)
}
// update / prefixSum / rangeSum: O(log n)   Space: O(n)

class RangeUpdateBIT(private val n: Int) {
    private val bit = LongArray(n + 2)                   // stores a difference array

    private fun add(index: Int, delta: Long) {
        var i = index + 1
        while (i <= n + 1) {
            bit[i] += delta
            i += i and -i
        }
    }

    fun rangeAdd(l: Int, r: Int, delta: Long) {          // add delta to a[l..r]
        add(l, delta)
        add(r + 1, -delta)
    }

    fun pointQuery(index: Int): Long {                   // value at one position = prefix sum of the differences
        var i = index + 1
        var sum = 0L
        while (i > 0) {
            sum += bit[i]
            i -= i and -i
        }
        return sum
    }
}
// Each operation: O(log n)

class RangeBIT(private val n: Int) {
    private val b1 = LongArray(n + 2)
    private val b2 = LongArray(n + 2)

    private fun add(b: LongArray, i1: Int, v: Long) {    // i1 is 1-indexed
        var i = i1
        while (i <= n + 1) {
            b[i] += v
            i += i and -i
        }
    }

    private fun sum(b: LongArray, i1: Int): Long {
        var i = i1
        var s = 0L
        while (i > 0) {
            s += b[i]
            i -= i and -i
        }
        return s
    }

    fun rangeAdd(l: Int, r: Int, x: Long) {              // a[l..r] += x, 0-based
        val left = l + 1
        val right = r + 1
        add(b1, left, x)
        add(b1, right + 1, -x)
        add(b2, left, x * (left - 1))
        add(b2, right + 1, -x * right)
    }

    private fun prefix(p1: Int): Long = sum(b1, p1) * p1 - sum(b2, p1)   // sum of the first p1 elements

    fun rangeSum(l: Int, r: Int): Long = prefix(r + 1) - prefix(l)
}
// Each operation: O(log n)

class SegmentTree(private val nums: IntArray) {
    private val n = nums.size
    private val tree = LongArray(4 * n)

    init {
        if (n > 0) build(1, 0, n - 1)
    }

    private fun build(node: Int, l: Int, r: Int) {
        if (l == r) {
            tree[node] = nums[l].toLong()                // leaf
            return
        }
        val mid = (l + r) / 2
        build(node * 2, l, mid)
        build(node * 2 + 1, mid + 1, r)
        tree[node] = tree[node * 2] + tree[node * 2 + 1] // combine the two halves
    }

    fun update(index: Int, value: Int) = update(1, 0, n - 1, index, value)

    private fun update(node: Int, l: Int, r: Int, index: Int, value: Int) {
        if (l == r) {
            tree[node] = value.toLong()
            return
        }
        val mid = (l + r) / 2
        if (index <= mid) update(node * 2, l, mid, index, value)
        else update(node * 2 + 1, mid + 1, r, index, value)
        tree[node] = tree[node * 2] + tree[node * 2 + 1]
    }

    fun query(ql: Int, qr: Int): Long = query(1, 0, n - 1, ql, qr)

    private fun query(node: Int, l: Int, r: Int, ql: Int, qr: Int): Long {
        if (qr < l || r < ql) return 0                   // no overlap: contributes nothing
        if (ql <= l && r <= qr) return tree[node]        // full overlap: use the stored answer
        val mid = (l + r) / 2
        return query(node * 2, l, mid, ql, qr) + query(node * 2 + 1, mid + 1, r, ql, qr)   // partial overlap
    }
}
// build: O(n)   update / query: O(log n)   Space: O(4n)

class IterativeSegmentTree(
    private val n: Int,
    private val identity: Int,
    private val combine: (Int, Int) -> Int
) {
    private val tree = IntArray(2 * n) { identity }

    constructor(values: IntArray, identity: Int, combine: (Int, Int) -> Int) :
        this(values.size, identity, combine) {
        for (i in values.indices) tree[n + i] = values[i]                // leaves
        for (i in n - 1 downTo 1) tree[i] = combine(tree[2 * i], tree[2 * i + 1])
    }

    fun update(index: Int, value: Int) {
        var i = index + n
        tree[i] = value
        while (i > 1) {
            i /= 2
            tree[i] = combine(tree[2 * i], tree[2 * i + 1])
        }
    }

    // query the inclusive range [l, r]
    fun query(l: Int, r: Int): Int {
        var lo = l + n
        var hi = r + n + 1                                               // half-open [lo, hi)
        var left = identity
        var right = identity
        while (lo < hi) {
            if ((lo and 1) == 1) left = combine(left, tree[lo++])        // lo is a right child: take it
            if ((hi and 1) == 1) right = combine(tree[--hi], right)      // hi - 1 is a left child: take it
            lo /= 2
            hi /= 2
        }
        return combine(left, right)
    }
}

