class LazySegmentTree(private val n: Int) {
    private val sum = LongArray(4 * n)
    private val lazy = LongArray(4 * n)                  // pending addition for the whole segment of a node

    private fun applyTag(node: Int, l: Int, r: Int, v: Long) {
        sum[node] += v * (r - l + 1)                     // every element in the segment gains v
        lazy[node] += v                                  // remember to pass it to the children later
    }

    private fun push(node: Int, l: Int, r: Int) {
        if (lazy[node] != 0L) {
            val mid = (l + r) / 2
            applyTag(node * 2, l, mid, lazy[node])
            applyTag(node * 2 + 1, mid + 1, r, lazy[node])
            lazy[node] = 0
        }
    }

    fun rangeAdd(ql: Int, qr: Int, v: Long) = rangeAdd(1, 0, n - 1, ql, qr, v)

    private fun rangeAdd(node: Int, l: Int, r: Int, ql: Int, qr: Int, v: Long) {
        if (qr < l || r < ql) return
        if (ql <= l && r <= qr) {
            applyTag(node, l, r, v)                      // fully covered: stop here and leave a tag
            return
        }
        push(node, l, r)                                 // push pending work down before going deeper
        val mid = (l + r) / 2
        rangeAdd(node * 2, l, mid, ql, qr, v)
        rangeAdd(node * 2 + 1, mid + 1, r, ql, qr, v)
        sum[node] = sum[node * 2] + sum[node * 2 + 1]
    }

    fun rangeSum(ql: Int, qr: Int): Long = rangeSum(1, 0, n - 1, ql, qr)

    private fun rangeSum(node: Int, l: Int, r: Int, ql: Int, qr: Int): Long {
        if (qr < l || r < ql) return 0
        if (ql <= l && r <= qr) return sum[node]
        push(node, l, r)
        val mid = (l + r) / 2
        return rangeSum(node * 2, l, mid, ql, qr) + rangeSum(node * 2 + 1, mid + 1, r, ql, qr)
    }
}
// rangeAdd / rangeSum: O(log n)   Space: O(8n)
// Rule: push before descending, recompute from the children on the way back up

// Map arbitrary values to ranks 1..m so they can be Fenwick or segment tree indexes
fun compress(nums: IntArray): Pair<IntArray, (Int) -> Int> {
    val sorted = nums.toSortedSet().toIntArray()                         // distinct values in order
    val rank: (Int) -> Int = { x -> java.util.Arrays.binarySearch(sorted, x) + 1 }   // 1-based rank
    return Pair(sorted, rank)
}
// Build: O(n log n)   rank(x): O(log n)

class NumArray(nums: IntArray) {
    private val values = nums.copyOf()
    private val bit = FenwickTree(nums)

    fun update(index: Int, value: Int) {
        val delta = (value - values[index]).toLong()     // the tree stores differences
        values[index] = value
        bit.update(index, delta)
    }

    fun sumRange(left: Int, right: Int): Int = bit.rangeSum(left, right).toInt()
}
// Constructor: O(n)   update / sumRange: O(log n)

class RangeMin(values: IntArray) {
    private val tree = IterativeSegmentTree(values, Int.MAX_VALUE) { a, b -> minOf(a, b) }

    fun update(index: Int, value: Int) = tree.update(index, value)

    fun minInRange(l: Int, r: Int): Int = tree.query(l, r)
}
// Fenwick trees cannot do this once values may increase, a segment tree can

fun countSmaller(nums: IntArray): List<Int> {
    val sorted = nums.toSortedSet().toIntArray()
    val m = sorted.size
    val bit = IntArray(m + 1)                            // counts of values seen so far, by rank

    fun add(rank: Int) {
        var i = rank
        while (i <= m) {
            bit[i]++
            i += i and -i
        }
    }

    fun countLess(rank: Int): Int {                      // how many inserted values have rank < given rank
        var i = rank - 1
        var s = 0
        while (i > 0) {
            s += bit[i]
            i -= i and -i
        }
        return s
    }

    val result = IntArray(nums.size)
    for (i in nums.indices.reversed()) {                 // scan from the right
        val rank = java.util.Arrays.binarySearch(sorted, nums[i]) + 1
        result[i] = countLess(rank)                      // smaller values already to the right
        add(rank)
    }
    return result.toList()
}
// Time: O(n log n)   Space: O(n)

fun countInversions(nums: IntArray): Long {
    val sorted = nums.toSortedSet().toIntArray()
    val m = sorted.size
    val bit = IntArray(m + 1)

    fun add(rank: Int) {
        var i = rank
        while (i <= m) { bit[i]++; i += i and -i }
    }

    fun countAtMost(rank: Int): Int {
        var i = rank
        var s = 0
        while (i > 0) { s += bit[i]; i -= i and -i }
        return s
    }

    var inversions = 0L
    for ((idx, x) in nums.withIndex()) {
        val rank = java.util.Arrays.binarySearch(sorted, x) + 1
        inversions += idx - countAtMost(rank)            // earlier elements that are strictly greater
        add(rank)
    }
    return inversions
}
// Time: O(n log n)   Space: O(n)
// An inversion is a pair i < j with nums[i] > nums[j]

fun lengthOfLIS(nums: IntArray): Int {
    val sorted = nums.toSortedSet().toIntArray()
    val tree = IterativeSegmentTree(sorted.size, 0) { a, b -> maxOf(a, b) }   // best LIS length ending at each value rank
    var best = 0
    for (x in nums) {
        val rank = java.util.Arrays.binarySearch(sorted, x)                    // 0-based
        val prev = if (rank == 0) 0 else tree.query(0, rank - 1)               // best among strictly smaller values
        val len = prev + 1
        tree.update(rank, maxOf(tree.query(rank, rank), len))
        best = maxOf(best, len)
    }
    return best
}
// Time: O(n log n)   Space: O(n)
// Useful when the DP needs 'best over all smaller values' with updates

class FenwickKth(private val n: Int) {
    private val tree = IntArray(n + 1)
    private val topBit = if (n > 0) 31 - Integer.numberOfLeadingZeros(n) else -1

    fun add(value: Int, delta: Int) {                    // value in 1..n, delta +1 inserts, -1 removes
        var i = value
        while (i <= n) {
            tree[i] += delta
            i += i and -i
        }
    }

    fun kth(k: Int): Int {                               // smallest value whose prefix count is at least k
        var pos = 0
        var remaining = k
        for (pw in topBit downTo 0) {
            val next = pos + (1 shl pw)
            if (next <= n && tree[next] < remaining) {
                pos = next                               // skip this whole block
                remaining -= tree[next]
            }
        }
        return pos + 1
    }
}
// add: O(log n)   kth: O(log n)   Requires values in 1..n (use compression otherwise)

class SubNode(val sum: Long, val prefix: Long, val suffix: Long, val best: Long)

fun leaf(x: Int) = SubNode(x.toLong(), x.toLong(), x.toLong(), x.toLong())

fun merge(a: SubNode, b: SubNode) = SubNode(
    sum = a.sum + b.sum,
    prefix = maxOf(a.prefix, a.sum + b.prefix),                      // best prefix of the combined segment
    suffix = maxOf(b.suffix, b.sum + a.suffix),                      // best suffix of the combined segment
    best = maxOf(a.best, b.best, a.suffix + b.prefix)                // best may cross the middle
)

class MaxSubarrayTree(private val nums: IntArray) {
    private val n = nums.size
    private val tree = arrayOfNulls<SubNode>(4 * n)

    init { build(1, 0, n - 1) }

    private fun build(node: Int, l: Int, r: Int) {
        if (l == r) { tree[node] = leaf(nums[l]); return }
        val mid = (l + r) / 2
        build(node * 2, l, mid)
        build(node * 2 + 1, mid + 1, r)
        tree[node] = merge(tree[node * 2]!!, tree[node * 2 + 1]!!)
    }

    fun update(index: Int, value: Int) = update(1, 0, n - 1, index, value)

    private fun update(node: Int, l: Int, r: Int, index: Int, value: Int) {
        if (l == r) { tree[node] = leaf(value); return }
        val mid = (l + r) / 2
        if (index <= mid) update(node * 2, l, mid, index, value)
        else update(node * 2 + 1, mid + 1, r, index, value)
        tree[node] = merge(tree[node * 2]!!, tree[node * 2 + 1]!!)
    }

    fun query(ql: Int, qr: Int): Long = query(1, 0, n - 1, ql, qr)!!.best

    private fun query(node: Int, l: Int, r: Int, ql: Int, qr: Int): SubNode? {
        if (qr < l || r < ql) return null
        if (ql <= l && r <= qr) return tree[node]
        val mid = (l + r) / 2
        val left = query(node * 2, l, mid, ql, qr)
        val right = query(node * 2 + 1, mid + 1, r, ql, qr)
        return when {
            left == null -> right
            right == null -> left
            else -> merge(left, right)
        }
    }
}
// update / query: O(log n)   The node stores enough facts to merge two halves

class NumMatrix(matrix: Array<IntArray>) {
    private val rows = matrix.size
    private val cols = matrix[0].size
    private val tree = Array(rows + 1) { IntArray(cols + 1) }
    private val values = Array(rows) { IntArray(cols) }

    init {
        for (r in 0 until rows) {
            for (c in 0 until cols) update(r, c, matrix[r][c])
        }
    }

    fun update(row: Int, col: Int, value: Int) {
        val delta = value - values[row][col]
        values[row][col] = value
        var i = row + 1
        while (i <= rows) {
            var j = col + 1
            while (j <= cols) {
                tree[i][j] += delta
                j += j and -j
            }
            i += i and -i
        }
    }

    private fun prefix(row: Int, col: Int): Int {                    // sum of the rectangle (0, 0) to (row, col)
        var sum = 0
        var i = row + 1
        while (i > 0) {
            var j = col + 1
            while (j > 0) {
                sum += tree[i][j]
                j -= j and -j
            }
            i -= i and -i
        }
        return sum
    }

    fun sumRegion(r1: Int, c1: Int, r2: Int, c2: Int): Int =
        prefix(r2, c2) - prefix(r1 - 1, c2) - prefix(r2, c1 - 1) + prefix(r1 - 1, c1 - 1)
}
// update / sumRegion: O(log rows * log cols)

fun applyUpdates(length: Int, updates: Array<IntArray>): LongArray {
    val bit = RangeUpdateBIT(length)
    for ((start, end, inc) in updates) {
        bit.rangeAdd(start, end, inc.toLong())
    }
    return LongArray(length) { bit.pointQuery(it) }
}
// Time: O((length + updates) log length)
// A plain difference array does this in O(length + updates) when all updates come before the queries

fun lazyDemo() {
    val tree = LazySegmentTree(8)
    tree.rangeAdd(0, 7, 5)                // every element becomes 5
    tree.rangeAdd(2, 4, 3)                // elements 2..4 become 8
    println(tree.rangeSum(0, 7))          // 8 * 5 + 3 * 3 = 49
    println(tree.rangeSum(2, 3))          // 8 + 8 = 16
}
// Both operations are O(log n) because pending additions are applied lazily
